class ChronosRuntime:
    def __init__(self, decay_rate: float = 0.995) -> None:
        self.time_matrix: Dict[int, float] = {}
        self.decay_rate: float = decay_rate
        self.lock = threading.Lock()

    def access_memory(self, address: int) -> float:
        now = time.time()
        with self.lock:
            if address not in self.time_matrix:
                self.time_matrix[address] = now
                return 0.0
            last = self.time_matrix[address]
            self.time_matrix[address] = now
        return max(0.0, now - last)

    def decay_memory(self) -> None:
        now = time.time()
        with self.lock:
            to_delete = []
            for address, ts in self.time_matrix.items():
                dt = max(0.0, now - ts)
                decay_factor = self.decay_rate ** dt
                if decay_factor < 0.01:
                    to_delete.append(address)
            for address in to_delete:
                del self.time_matrix[address]


