            if 0 <= address < self.capacity:
                self.memory[address] = float(value)
                self.frequency_map[address] = self.frequency_map.get(address, 0) + 1

    def read_memory(self, address: int) -> Optional[float]:
        with self.lock:
            if 0 <= address < self.capacity:
                return self.memory[address]
            return None

    def calculate_resonance(self) -> float:
