class SecureDeployment:
    def __init__(self, key_length_bits: int = 256) -> None:
        kl = max(128, key_length_bits)
        self.key = os.urandom(kl // 8)

    def _keystream(self, nonce: bytes, length: int) -> bytes:
        out = bytearray()
        counter = 0
        while len(out) < length:
            h = hashlib.sha256(self.key + nonce + counter.to_bytes(8, "big")).digest()
            need = min(len(h), length - len(out))
            out.extend(h[:need])
            counter += 1
        return bytes(out)

    def encrypt(self, data: bytes, nonce: Optional[bytes] = None) -> bytes:
        if nonce is None:
            nonce = os.urandom(16)
        ks = self._keystream(nonce, len(data))
        ct = bytes(a ^ b for a, b in zip(data, ks))
        return nonce + ct

    def decrypt(self, blob: bytes) -> bytes:
        if len(blob) < 16:
            return b""
        nonce = blob[:16]
        ct = blob[16:]
        ks = self._keystream(nonce, len(ct))
        return bytes(a ^ b for a, b in zip(ct, ks))

    def sign(self, data: bytes) -> str:
        return hmac.new(self.key, data, hashlib.sha256).hexdigest()


