            idx = i % L
            key = f"param_{idx}"
            self.model_parameters[idx] = self.optimizer.update_parameter(self.model_parameters[idx], grad, key)
            out += self.model_parameters[idx] * v
        self.runtime.decay_memory()
        return float(out)

    def generate_response(self, input_text: str) -> str:
        processed = self.process_input(input_text)
