    llm = RootLLM()
    stdin = sys.stdin
    stdout = sys.stdout
    while True:
        try:
            stdout.write("Enter your query (or type 'exit'): ")
            stdout.flush()
            line = stdin.readline()
            if not line:
                break
            user_input = line.rstrip("\n").strip()
            if user_input.lower() == "exit":
                break
            response = llm.generate_response(user_input)
            stdout.write("LLM Response: ")
            stdout.write(response)
            stdout.write("\n")
            stdout.flush()
        except Exception as e:
            try:
                msg = {"error": str(e)}
                sys.stdout.write(json.dumps(msg, ensure_ascii=False) + "\n")
                sys.stdout.flush()
            except Exception:
                pass


if __name__ == "__main__":
    main()
